#!/usr/bin/env node
/**
 * apply-lt-names-inat-fixes.mjs
 *
 * Idempotent script that applies curated iNat-only contamination fixes from
 * data/lt-names-inat-fixes.json to data/lt-names.json. Adds an
 * _appliedInatFix marker to each modified entry so re-runs are safe.
 *
 * Usage:
 *   node scripts/apply-lt-names-inat-fixes.mjs           # dry-run (default)
 *   node scripts/apply-lt-names-inat-fixes.mjs --apply   # actually write
 *
 * Generated by task #42 (Mass audit iNat-only LT names, 2026-05-24).
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, '..');
const LT_NAMES_PATH = resolve(ROOT, 'data', 'lt-names.json');
const FIXES_PATH = resolve(ROOT, 'data', 'lt-names-inat-fixes.json');
const BACKUP_PATH = resolve(
  ROOT,
  'data',
  `lt-names.backup.inat.${new Date().toISOString().slice(0, 10)}.json`
);

const APPLY = process.argv.includes('--apply');

function log(...args) {
  console.log(...args);
}

function applyFix(entry, fix, genus) {
  if (entry._appliedInatFix && entry._appliedInatFix.action === fix.action) {
    return { changed: false, reason: 'already_applied' };
  }

  const before = JSON.parse(JSON.stringify(entry));
  const changes = [];

  switch (fix.action) {
    case 'clear_ltname': {
      if (entry.ltName) {
        const droppedName = entry.ltName;
        entry.ltName = null;
        // Also drop from ltAllForms if it was the canonical
        if (Array.isArray(entry.ltAllForms)) {
          entry.ltAllForms = entry.ltAllForms.filter((s) => s !== droppedName);
        }
        // Drop the inat raw entry to break re-population on next build
        if (entry.raw && typeof entry.raw === 'object') {
          if (entry.raw.inat) {
            entry.raw._inat_quarantined = entry.raw.inat;
            entry.raw.inat = null;
            changes.push('raw_inat_quarantined');
          }
        }
        changes.push('ltName_cleared');
      } else {
        return { changed: false, reason: 'ltName_already_null' };
      }
      break;
    }

    case 'keep': {
      // No-op — annotate confidence promotion or audit marker only
      // We do not bump confidence automatically — audit confirmation is meta only
      return { changed: false, reason: 'keep_no_change' };
    }

    case 'manual_review': {
      // Tag entry so dashboards / future audits flag it
      if (entry._needsManualReview) {
        return { changed: false, reason: 'already_flagged' };
      }
      entry._needsManualReview = {
        at: new Date().toISOString(),
        reason: fix.reason,
        suggestedReplacement: fix.suggestedReplacement ?? null,
      };
      changes.push('flagged_for_manual_review');
      break;
    }

    default:
      log(`  WARNING: unknown action "${fix.action}" for ${genus}`);
      return { changed: false, reason: 'unknown_action' };
  }

  if (changes.length === 0) {
    return { changed: false, reason: 'no_diff' };
  }

  entry._appliedInatFix = {
    at: new Date().toISOString(),
    action: fix.action,
    category: fix.category,
    reason: fix.reason,
    evidence: fix.evidence,
    changes,
    before: {
      ltName: before.ltName,
    },
  };

  return { changed: true, changes };
}

function main() {
  log(`[apply-lt-names-inat-fixes] mode = ${APPLY ? 'APPLY' : 'DRY-RUN'}`);
  log(`[apply-lt-names-inat-fixes] reading ${LT_NAMES_PATH}`);
  const ltData = JSON.parse(readFileSync(LT_NAMES_PATH, 'utf8'));
  log(`[apply-lt-names-inat-fixes] reading ${FIXES_PATH}`);
  const fixesData = JSON.parse(readFileSync(FIXES_PATH, 'utf8'));

  const counters = {
    clearLtNameApplied: 0,
    manualReviewFlagged: 0,
    keepNoOp: 0,
    skipped: 0,
    notFound: [],
  };

  for (const [genus, fix] of Object.entries(fixesData.fixes || {})) {
    const entry = ltData.ltNames[genus];
    if (!entry) {
      counters.notFound.push(genus);
      continue;
    }
    const result = applyFix(entry, fix, genus);
    if (result.changed) {
      if (fix.action === 'clear_ltname') counters.clearLtNameApplied++;
      else if (fix.action === 'manual_review') counters.manualReviewFlagged++;
      log(`  [APPLIED] ${genus.padEnd(16)} (${fix.action.padEnd(14)}): ${result.changes.join(', ')}`);
    } else {
      if (fix.action === 'keep') counters.keepNoOp++;
      else counters.skipped++;
      const tag = fix.action === 'keep' ? '[KEEP]   ' : '[SKIP]   ';
      log(`  ${tag} ${genus.padEnd(16)} (${fix.action.padEnd(14)}): ${result.reason}`);
    }
  }

  log('\n--- Summary ---');
  log(`  clear_ltname applied:     ${counters.clearLtNameApplied}`);
  log(`  manual_review flagged:    ${counters.manualReviewFlagged}`);
  log(`  keep (no change):         ${counters.keepNoOp}`);
  log(`  skipped (already done):   ${counters.skipped}`);
  if (counters.notFound.length) {
    log(`  Genera not found in lt-names.json: ${counters.notFound.join(', ')}`);
  }

  if (!APPLY) {
    log('\n[DRY-RUN] No file written. Re-run with --apply to persist changes.');
    return;
  }

  log(`\n[BACKUP] writing ${BACKUP_PATH}`);
  writeFileSync(BACKUP_PATH, readFileSync(LT_NAMES_PATH));

  ltData._lastInatAuditApplied = {
    at: new Date().toISOString(),
    fixesFile: 'data/lt-names-inat-fixes.json',
    task: '#42',
    clearLtNameApplied: counters.clearLtNameApplied,
    manualReviewFlagged: counters.manualReviewFlagged,
  };

  log(`[WRITE] writing ${LT_NAMES_PATH}`);
  writeFileSync(LT_NAMES_PATH, JSON.stringify(ltData, null, 2));
  log('[DONE] lt-names.json updated.');
}

main();
